DELETE from `sys_config` where param_key = "asset_chart_export_header";
INSERT INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'asset_chart_export_header', '{\"cn\":{\"图表组名\":\"组名 \\n示例: default\",\"*图表名称\":\"图表名称(必填) \\n示例: CPU使用率\",\"*图表类型\":\"图表类型(必填) 可选: 曲线图,柱状图,表格,堆叠区域图,SingleStat,URL,告警列表,文本,图表组,Diagram \\n示例: 曲线图\",\"变量类型\":\"变量类型 当类型是 template 时必填，可选:Asset,Endpoint \\n示例: Asset\",\"*宽度\":\"宽度(必填) 可选：1-12 \\n示例: 10\",\"*高度\":\"高度(必填),可选：1-12 \\n示例: 10\",\"单位\":\"单位(必填) 可选: \\nMisc: none,short,percent(0-100),percent(0.0-1.0),local format\\nData: bits,bytes,kilobytes,megabytes,gigabytes,terabytes,petabytes\\nDataRate: packets/sec,bits/sec,bytes/sec,kilobytes/sec,kilobits/sec,megabytes/sec,megabits/sec,gigabytes/sec,gigabits/sec,terabytes/sec,terabits/sec,petabytes/sec,petabits/sec\\nTime: Hertz(1/s),nanoseconds(ns),microseconds(us),milliseconds(ms),seconds(s),minutes(m),hours(h),days(d),YYYY-MM-DD HH:mm:ss,MM/DD/YYYY h:mm:ss a \\n示例: short\",\"*参数\":\"单位 根据type不同，内容不同，格式为JSON格式 \\n示例: {\\\"statistics\\\":\\\"average\\\"}\",\"元素\":\"当type=line，bar，stackArea时，包含 elements key，值为对象数组。\\n 示例:[{\\\"expression\\\":\\\"sum(up)\\\",\\\"legend\\\":\\\"test\\\"}]\"},\"en\":{\"Chart Group\":\"Group name \\nExample: default\",\"*Chart Title\":\"Chart title(Required) \\nExample: CPU usage\",\"*Chart Type\":\"Chart type(Required) Optional: Line Chart,Histogram,Table,Stack Area,SingleStat,URL,Alert list,Text,Group,Diagram \\nExample: Line Chart\",\"Variable type\":\"Variable type Required when type is template, optional: Asset, Endpoint \\nExample: Asset\",\"*Width\":\"width(Required) Optional：1-12 \\nExample: 10\",\"*Height\":\"height(Required),Optional：1-12 \\nExample: 10\",\"Unit\":\"unit(Required) Optional: \\nMisc: none,short,percent(0-100),percent(0.0-1.0),local format\\nData: bits,bytes,kilobytes,megabytes,gigabytes,terabytes,petabytes\\nDataRate: packets/sec,bits/sec,bytes/sec,kilobytes/sec,kilobits/sec,megabytes/sec,megabits/sec,gigabytes/sec,gigabits/sec,terabytes/sec,terabits/sec,petabytes/sec,petabits/sec\\nTime: Hertz(1/s),nanoseconds(ns),microseconds(us),milliseconds(ms),seconds(s),minutes(m),hours(h),days(d),YYYY-MM-DD HH:mm:ss,MM/DD/YYYY h:mm:ss a \\nExample: short\",\"*Parameter\":\"Parameters match type，The format is JSON format \\nExample: {\\\"statistics\\\":\\\"average\\\"}\",\"Elements\":\"When the type is line, table, stackArea, singleStat, histogram, it contains elements key and the value is an object array.\\nExample:[{\\\"expression\\\":\\\"sum(up)\\\",\\\"legend\\\":\\\"test\\\"}]\"}}', 1, NULL);

DELETE from `sys_config` where param_key = "dc_export_header";
INSERT INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'dc_export_header', '{\"cn\":{\"*名称\":\"名称（必填）\\n示例：xxx 数据中心\",\"位置\":\"位置 \\n示例：你的城市\",\"电话\":\"电话 \\n示例：9684631\",\"负责人\":\"机房负责人 \\n示例：admin\",\"经度\":\"经度 (-180,180) \\n示例：80\",\"纬度\":\"纬度 (-90,90) \\n示例：80\",\"*状态\":\"状态(必填) 可选：ON/OFF \\n示例：ON\"},\"en\":{\"*Name\":\"Name(Required) \\nExample: xxx datacenter\",\"Location\":\"Location \\nExample: your city\",\"Telephone\":\"Telephone \\nExample: 9684631\",\"Principal\":\"Principal \\nExample: admin\",\"Longitude\":\"Longitude (-180,180) \\nExample: 80\",\"Latitude\":\"Latitude (-90,90) \\nExample: 80\",\"*State\":\"State(Required) Optional: ON/OFF \\nExample: ON\"}}', 1, 'dc 导入导出表头信息');


DELETE from `sys_config` where param_key = "model_export_header";
INSERT INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'model_export_header', '{\"cn\":{\"*名称\":\"名称（必填）\\n示例：DELL-D3\",\"*品牌\":\"品牌（必填）\\n示例：DELL\",\"图表\":\"Asset 类型的图表模板 \\n示例：服务器模板,基本模板\",\"描述\":\"描述 \\n示例：DELL-D3\"},\"en\":{\"*Name\":\"Name(Required) \\nExample: DELL-D3\",\"*Brand\":\"Brand(Required) \\nExample: DELL\",\"Chart templates\":\"Asset chart templates  \\nExample: Server Template,Basic Template\",\"Description\":\"Description \\nExample: This is dell-d3\"}}', 1, 'asset model 导入导出表头信息');

DELETE from `sys_config` where param_key = "cabinet_export_header";
INSERT INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'cabinet_export_header', '{\"cn\":{\"*名称\":\"名称（必填）\\n示例：机柜 1-1\",\"*数据中心\":\"数据中心（必填） \\n示例：xxx数据中心\",\"U位\":\"U位 \\n示例：10\",\"所在行\":\"所在行 \\n示例：1\",\"所在列\":\"所在列 \\n示例：1\",\"描述\":\"描述 \\n示例：2011年入库\"},\"en\":{\"*Name\":\"Name(Required) \\nExample: Cabinet 1-1\",\"*Data center\":\"Data center(Required) \\nExample: xxx data center\",\"U size\":\"U size (1,47)\\nExample: 10\",\"Row\":\"Row of data center \\nExample: 1\",\"Column\":\"Column of data center \\nExample: 1\",\"Description\":\"Description  \\nExample: In 2011\"}}', 1, 'cabinet 导入导出表头信息');
